<script setup lang="ts">
import {computed,ref} from 'vue';import RoomPositionMap from './RoomPositionMap.vue';import {ArrowRight,Layers3,Server} from 'lucide-vue-next';import type {State} from './model';
const props=defineProps<{state:State;projectId:string;siteId:string;selectedModule:string;busy?:boolean}>();
const emit=defineEmits<{open:[moduleId:string,rackId?:string];room:[siteId:string];move:[moduleId:string,siteId:string];position:[moduleId:string,position:{x:number;y:number}|null,rotation?:number]}>();
const showList=ref(false);
const modules=computed(()=>props.state.modules.filter(m=>m.siteId===props.siteId));
function startMove(e:DragEvent,id:string){if(props.busy){e.preventDefault();return}e.dataTransfer!.setData('aom-module',id)}
function dropMove(e:DragEvent,id:string){e.preventDefault();const module=e.dataTransfer?.getData('aom-module');if(module&&id!==props.siteId)emit('move',module,id)}
</script>
<template><section class="panel room-overview"><div class="panel-heading"><div><Layers3 :size="18"/><h2>微模块总览</h2><span class="text-badge">{{modules.length}} 个微模块</span></div><button class="text-button" @click="showList=!showList">{{showList?'查看位置图':'模块列表'}}</button></div><RoomPositionMap v-if="!showList" :state="state" :site-id="siteId" :busy="busy" @open="emit('open',$event)" @position="(id,position,rotation)=>emit('position',id,position,rotation)"/><div v-show="showList"><div v-if="state.sites.filter(s=>s.projectId===projectId).length>1" class="module-move-targets"><span>拖动模块到目标机房：</span><button v-for="room in state.sites.filter(s=>s.projectId===projectId)" :key="room.id" :data-module-room="room.id" @dragover.prevent @drop="dropMove($event,room.id)" @click="emit('room',room.id)">{{room.name}}</button></div><div class="room-map module-summary-grid"><button v-for="m in modules" :key="m.id" class="overview-module module-summary-card" :draggable="!busy" @dragstart="startMove($event,m.id)" :aria-label="`进入微模块 ${m.name}`" @click="emit('open',m.id)"><div class="overview-module-heading"><div><span class="eyebrow">{{m.point||'自定义点位'}}</span><h3>{{m.name}}</h3><p>{{m.productModel||'型号待录入'}}</p></div><ArrowRight :size="17"/></div><div class="module-schematic" aria-hidden="true"><div class="schematic-row"><i v-for="n in Math.min(m.rackLeft,8)" :key="n"></i><span v-if="m.rackLeft>8">+{{m.rackLeft-8}}</span></div><div v-if="m.type==='double'" class="schematic-aisle">冷通道</div><div v-if="m.type==='double'" class="schematic-row"><i v-for="n in Math.min(m.rackRight,8)" :key="n"></i><span v-if="m.rackRight>8">+{{m.rackRight-8}}</span></div></div><div class="overview-module-footer"><span><Server :size="12"/>{{m.type==='double'?'双排':'单排'}} · {{m.rackLeft+m.rackRight}} 柜</span><span>{{state.devices.filter(d=>d.moduleId===m.id).length}} 台设备</span></div></button></div></div></section></template>
